def VIS(x=110,y=0,s=1):
    return (f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2.5">'
     '<path d="M-30 70 q-16 -10 -22 -30" fill="none" stroke="#3b6fd0" stroke-width="7"/><path d="M30 70 q16 -10 22 -30" fill="none" stroke="#3b6fd0" stroke-width="7"/>'
     '<circle cx="-54" cy="36" r="9" fill="#fff"/><circle cx="54" cy="36" r="9" fill="#ffd60a"/>'
     '<circle cy="50" r="14" fill="#3b6fd0"/><path d="M-12 36 h24 l-4 -18 h-16z" fill="#ffd60a"/>'
     '<path d="M-24 150 q-4 -66 24 -84 q28 18 24 84z" fill="#ffd60a"/><path d="M-30 96 q-14 10 -16 24" fill="none" stroke="#3b6fd0" stroke-width="7"/><path d="M30 96 q14 10 16 24" fill="none" stroke="#3b6fd0" stroke-width="7"/>'
     '<circle cx="-46" cy="124" r="6" fill="#f08aa6"/><path d="M46 124 v-16" stroke="#7a5a3a" stroke-width="5"/></g>')
def BHISMA(x=110,y=120,s=1):
    return (f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2">'
     +''.join(f'<path d="M{-50+10*k} 10 l{-6+(k%3)*6} -34" stroke="#7a5a3a" stroke-width="2"/>' for k in range(11))
     +'<path d="M-56 -16 h112 v8 h-112z" fill="#fff"/><circle cx="-64" cy="-18" r="10" fill="#f2c79b"/><path d="M-70 -12 q6 10 12 0" fill="#fff"/></g>')
def BOOK(x,y,t='',s=1): return f'<g transform="translate({x} {y}) scale({s})"><rect x="-22" y="-16" width="44" height="32" fill="#fff3b0" stroke="#111" stroke-width="2"/><path d="M0 -16 v32" stroke="#111"/>'+(f'<text y="4" text-anchor="middle" {F} font-size="7">{t}</text>' if t else '')+'</g>'
