 svg=svg('A sage and the four-armed Lord facing each other like mirror images',person(60,146,'#fff','#f2c79b',.9)+BOOK(84,104,'',.6)+VIS(160,10,.6)+f'<text x="110" y="90" text-anchor="middle" {F} font-size="24">=</text>',B),
