 svg=svg('A still flame in a lamp, unmoving while clouds swirl around it',''.join(f'<path d="M{20+40*k} {40+30*(k%2)} q20 -20 40 0" fill="none" stroke="#9fd3f0" stroke-width="4"/>' for k in range(5))+'<g transform="translate(110 120)" stroke="#111" stroke-width="2"><path d="M-24 0 h48 l-6 12 h-36z" fill="#e0a800"/><path d="M0 0 q-12 -26 0 -40 q12 14 0 40z" fill="#ff8c1a"/></g>'+lab(110,152,'NITYA · ŚUDDHA',9),B),
