 svg=svg('Chains breaking from a person\'s wrists as they think of the Lord',person(110,146,'#ff8c1a','#f2c79b',.9)+''.join(f'<circle cx="{60+8*k}" cy="{116}" r="4" fill="none" stroke="#555" stroke-width="2"/><circle cx="{160-8*k}" cy="{116}" r="4" fill="none" stroke="#555" stroke-width="2"/>' for k in range(3))+'<path d="M82 112 l6 8 M138 112 l-6 8" stroke="#e63946" stroke-width="3"/>'+lab(110,30,'SMARAṆA',12),B),
