 svg=svg('Four small panels: a person offering a flower, sitting in meditation, singing, and bowing',''.join(f'<rect x="{8+52*k}" y="40" width="48" height="90" fill="#fff" stroke="#111" stroke-width="2"/>'+person(32+52*k,118,'#ff8c1a','#f2c79b',.42)+lab(32+52*k,144,t,7) for k,t in enumerate(['ARCANĀ','DHYĀNA','STUTI','NAMAS']))+lab(110,26,'WITH BHAKTI',11),B),
